function parseCSV(text) {
  const rows = [];
  let currentRow = [''];
  let inQuotes = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    const next = text[i + 1];
    if (c === '"') {
      if (inQuotes && next === '"') {
        currentRow[currentRow.length - 1] += '"';
        i++;
      } else {
        inQuotes = !inQuotes;
      }
    } else if (c === ',' && !inQuotes) {
      currentRow.push('');
    } else if ((c === '\r' || c === '\n') && !inQuotes) {
      if (c === '\r' && next === '\n') i++;
      if (currentRow.length > 1 || currentRow[0].trim() !== '') {
        rows.push(currentRow.map((col) => col.trim()));
      }
      currentRow = [''];
    } else {
      currentRow[currentRow.length - 1] += c;
    }
  }
  if (currentRow.length > 1 || currentRow[0].trim() !== '') {
    rows.push(currentRow.map((col) => col.trim()));
  }
  return rows;
}

